import type {TCodespaceState} from '../types/codespace-types'
import {
  CodespaceStatus,
  type ConnectionEvent,
  CopilotLicenseType,
  CopilotPlan,
  type Entitlements,
  type ErrorEvent,
  initialState,
  Service,
  Status,
  type StatusEvent,
  workbenchStoreReducer,
  type WorkbenchStoreState,
} from '../utilities/workbench-store-reducer'

export {
  AcaStatus,
  AgentStatus,
  CodespaceStatus,
  CopilotLicenseType,
  CopilotPlan,
  EntitledService,
  initialState,
  Service,
  Status,
} from '../utilities/workbench-store-reducer'

const mapCodespaceStatus = (status: TCodespaceState): CodespaceStatus => {
  let mappedStatus: CodespaceStatus = CodespaceStatus.DISCONNECTED
  switch (status) {
    case 'none': {
      mappedStatus = Status.DISCONNECTED
      break
    }
    case 'creating':
    case 'starting': {
      mappedStatus = CodespaceStatus.STARTING
      break
    }
    case 'failed': {
      mappedStatus = Status.ERROR
      break
    }
    case 'ready': {
      mappedStatus = Status.CONNECTED
      break
    }
  }
  return mappedStatus
}

export type WorkbenchStoreContext = WorkbenchStoreState & {
  hasServiceErrors: boolean
  isModelThrottled: boolean
  setReadOnly: (readOnly: boolean) => void
  onError(event: ErrorEvent): void
  onConnected(event: ConnectionEvent): void
  onDisconnected(event: ConnectionEvent): void
  onIdle(event: ConnectionEvent): void
  onStatus(event: StatusEvent): void
  onCodespaceStatus(event: TCodespaceState): void
  onSuccess(event: ConnectionEvent): void
  reloadQuota(): void
}

export const WorkbenchStoreContext = React.createContext<WorkbenchStoreContext | undefined>(undefined)

export function WorkbenchStoreProvider({children}: React.PropsWithChildren) {
  const [state, dispatch] = useReducer(workbenchStoreReducer, initialState)
  const {licenseType, plan} = useAppPayload<CopilotChatPayload>()

  const [, reloadQuota] = useCopilotChatEntitlement(licenseType, plan)
  const isThrottleFeatureEnabled = useFeatureFlag('spark_log_rate_limit_event')

  const {data: entitlement} = useQuery<Entitlements>({
    queryKey: ['spark', 'entitlement'],
    queryFn: async () => {
      const response = await verifiedFetchJSON('/spark/entitlement')

      if (!response.ok) {
        throw new Error(`Failed to retrieve entitlements (${response.status} on ${response.url})`)
      }

      return (await response.json()) as Entitlements
    },
    placeholderData: initialState.entitlement,
    staleTime: 1000 * 60 * 1, // 1 minute
    refetchOnWindowFocus: 'always',
    refetchInterval: 1000 * 60 * 1, // 1 minutes
  })

  const {data: throttleStatus} = useQuery<{throttled: boolean}>({
    queryKey: ['spark', 'throttle_status'],
    queryFn: async () => {
      const response = await verifiedFetchJSON('/copilot/spark/throttle_status')

      if (!response.ok) {
        throw new Error(`Failed to retrieve throttle status (${response.status} on ${response.url})`)
      }

      return (await response.json()) as {throttled: boolean}
    },
    placeholderData: {throttled: false},
    staleTime: 1000 * 60 * 1, // 1 minute
    refetchOnWindowFocus: 'always',
    refetchInterval: 1000 * 60 * 1, // 1 minutes
    enabled: isThrottleFeatureEnabled,
  })

  const setReadOnly = useStableCallback((value: boolean) => {
    dispatch({type: value ? 'READ_ONLY' : 'WRITABLE'})
  })

  const onError = useStableCallback((event: ErrorEvent) => {
    dispatch({type: 'ERROR', payload: event})
  })

  const onConnected = useStableCallback((event: ConnectionEvent) => {
    dispatch({type: 'CONNECTED', payload: event})
  })

  const onDisconnected = useStableCallback((event: ConnectionEvent) => {
    dispatch({type: 'DISCONNECTED', payload: event})
  })

  const onIdle = useStableCallback((event: ConnectionEvent) => {
    dispatch({type: 'IDLE', payload: event})
  })

  const onStatus = useStableCallback((event: StatusEvent) => {
    dispatch({type: 'STATUS', payload: event})
  })

  const onCodespaceStatus = useStableCallback((event: TCodespaceState) => {
    dispatch({
      type: 'STATUS',
      payload: {
        service: Service.CODESPACE,
        status: mapCodespaceStatus(event),
      },
    })
  })

  const onSuccess = useStableCallback((event: ConnectionEvent) => {
    dispatch({type: 'CONNECTED', payload: event})
  })

  const hasServiceErrors = useMemo(() => {
    return Object.values(state.status).some(s => s === Status.ERROR)
  }, [state.status])

  const isModelThrottled = throttleStatus?.throttled ?? false

  const value = useMemo<WorkbenchStoreContext>(
    () => ({
      ...state,
      hasServiceErrors,
      entitlement: entitlement ?? state.entitlement,
      isModelThrottled,
      setReadOnly,
      onError,
      onConnected,
      onDisconnected,
      onIdle,
      onStatus,
      onCodespaceStatus,
      onSuccess,
      reloadQuota,
    }),
    [
      state,
      hasServiceErrors,
      isModelThrottled,
      entitlement,
      setReadOnly,
      onError,
      onConnected,
      onDisconnected,
      onIdle,
      onStatus,
      onCodespaceStatus,
      onSuccess,
      reloadQuota,
    ],
  )
  return <WorkbenchStoreContext.Provider value={value}>{children}</WorkbenchStoreContext.Provider>
}

export function useWorkbenchStore() {
  const context = useContext(WorkbenchStoreContext)
  if (!context) {
    throw new Error('useWorkbenchStore must be used within a WorkbenchStoreProvider')
  }
  return context
}

type GlobalReadOnly = [boolean, (readOnly: boolean) => void, boolean, boolean]
/**
 * @returns {GlobalReadOnly} A tuple containing:
 * - `readOnly`: A boolean indicating if the workbench is in read-only mode based on staticReadOnly, entitlementsQuotaReadOnly, and the status of the codespace.
 * - `setReadOnly`: A function to set the static read-only state, intended to be a kill switch
 * - `staticReadOnly`: A static boolean toggled by setReadOnly
 * - `entitlementsQuotaReadOnly`: A boolean indicating if the read-only state is due to entitlements quota.
 */
export function useGlobalReadOnly(): GlobalReadOnly {
  const {status, readOnly: staticReadOnly, setReadOnly, entitlement} = useWorkbenchStore()
  const isReadOnlyEnabled = isFeatureEnabled('workbench_store_readonly')

  // using status.X syntax instead of status[Service.X] to allow to memoizing against specific status fields
  const entitlementsQuotaReadOnly = useMemo(() => {
    const {licenseType, plan, quotas} = entitlement.copilot
    const chatQuotaExceeded = (quotas?.remaining?.chatPercentage ?? 0) <= 0
    const premiumInteractionsQuotaExceeded = (quotas?.remaining?.premiumInteractionsPercentage ?? 0) <= 0
    const isLicensedLimited = licenseType === CopilotLicenseType.LicensedLimited
    const isPaidPlan =
      plan === CopilotPlan.IndividualPro ||
      plan === CopilotPlan.IndividualProPlus ||
      plan === CopilotPlan.Business ||
      plan === CopilotPlan.Enterprise

    const copilotQuotaExceeded =
      (isLicensedLimited && chatQuotaExceeded) || (isPaidPlan && premiumInteractionsQuotaExceeded)

    // Codespaces quota exceeded
    const concurrentSparksAllowed = entitlement.codespaces_sessions.allowed
    // Codespace compute hours quota exceeded
    // TODO: Re-enable when compute hours quota returns a value
    // const computeHoursQuotaExceeded = entitlement.codespaces_compute.quotas.remaining.computeHoursPercentage <= 0

    return (copilotQuotaExceeded && !quotas?.overagesEnabled) || !concurrentSparksAllowed
  }, [entitlement])

  // using status.X syntax instead of status[Service.X] to allow to memoizing against specific status fields
  const readOnly = useMemo(
    () =>
      isReadOnlyEnabled &&
      (staticReadOnly || entitlementsQuotaReadOnly || [status.codespace].some(s => s !== Status.CONNECTED)),
    [status.codespace, staticReadOnly, isReadOnlyEnabled, entitlementsQuotaReadOnly],
  )
  const value = useMemo<GlobalReadOnly>(
    () => [readOnly, setReadOnly, staticReadOnly, entitlementsQuotaReadOnly],
    [readOnly, setReadOnly, staticReadOnly, entitlementsQuotaReadOnly],
  )
  return value
}

