import type {CommitData} from '../types/file-syncer-v2-types'
import type {Iteration} from '../types/workbench-types'

export interface CommitDataToIterationRefs {
  iterationsInDb: Iteration[]
  localStateRefinements: Iteration[]
}

/**
 * Converts commit data to an Iteration object, merging with data from DB and local state.
 *
 * This function looks up iteration data from both DB and local state to ensure we don't
 * lose suggestions that were set locally but not yet persisted to DB.
 *
 * Prefers local state suggestions (most recent) over DB suggestions.
 */
export function commitDataToIteration(commitData: CommitData, refs: CommitDataToIterationRefs): Iteration {
  const iterationInDb = refs.iterationsInDb.find(ref => ref.sha === commitData.sha)
  const iterationInLocalState = refs.localStateRefinements.find(ref => ref.sha === commitData.sha)

  const iteration_type =
    iterationInDb?.iteration_type ??
    iterationInLocalState?.iteration_type ??
    (commitData.message?.startsWith('Generated by Spark:') ? 'ai' : 'user')

  // Prefer local state suggestions (most recent) over DB suggestions, falling back to empty array
  const suggestions =
    (iterationInLocalState?.suggestions?.length ? iterationInLocalState.suggestions : null) ??
    (iterationInDb?.suggestions?.length ? iterationInDb.suggestions : null) ??
    []

  const files = iterationInDb?.files ?? iterationInLocalState?.files ?? {}
  const id = iterationInDb?.id ?? iterationInLocalState?.id
  const parentId = iterationInDb?.parentId ?? iterationInLocalState?.parentId ?? null

  let prompt = iterationInDb?.prompt ?? iterationInLocalState?.prompt
  if (iteration_type === 'ai' && !prompt) {
    prompt = commitData.message?.replace('Generated by Spark:', '').trim()
  }

  return {
    ...commitData,
    id,
    parentId,
    files,
    prompt,
    iteration_type,
    suggestions,
  }
}
