/*
 * Shown when user accounts don't have an assigned Copilot billing account.
 */

import {Banner, LinkButton} from '@primer/react'

export function CopilotBillingAssignmentBanner() {
  const description = `Before you can use GitHub Spark, you need to pick a "Usage billed to" option in your Copilot settings. Update your settings, then try again.`

  const url = `https://github.com/settings/copilot/features`

  const primaryAction = (
    <LinkButton as="a" href={url} target="_blank" rel="noopener noreferrer">
      Update your settings
    </LinkButton>
  )
  const title = 'Billing issue with your account.'
  const variant = 'critical'

  return (
    <Banner
      className="rounded-0"
      style={{outline: 'none'}}
      description={description}
      hideTitle
      primaryAction={primaryAction}
      title={title}
      variant={variant}
    />
  )
}

try{ CopilotBillingAssignmentBanner.displayName ||= 'CopilotBillingAssignmentBanner' } catch {}